-- Phase 2 cloud sync bookkeeping for this install only. Never synced and never in a backup:
-- a restored copy of another install's state would make this one skip or repeat rows.

-- How far this install has pulled: name 'pull', upto = the server sequence number read up to.
CREATE TABLE cloud_sync_cursors (
  name        TEXT PRIMARY KEY,
  upto        INTEGER NOT NULL DEFAULT -1,
  updated_at  INTEGER NOT NULL
);

-- Rows changed on this install and not pushed yet. Filled by the triggers below, not by the
-- clock: a row edited while the phone's clock is behind another device's is still pushed.
-- stamp grows with every change, so an edit made during a push is not cleared by it.
CREATE TABLE cloud_sync_outbox (
  tbl     TEXT NOT NULL,
  row_id  INTEGER NOT NULL,
  stamp   INTEGER NOT NULL,
  PRIMARY KEY (tbl, row_id)
);
CREATE INDEX idx_cloud_sync_outbox_stamp ON cloud_sync_outbox (stamp);

-- Holds one row while pulled rows are merged, so the triggers do not queue them to be pushed back.
CREATE TABLE cloud_sync_pulling (
  started_at  INTEGER PRIMARY KEY
);

-- One line per trigger: the Android plugin splits scripts on a semicolon at a line end.
-- Update, then insert if missing, rather than INSERT OR REPLACE: an upsert in the statement that
-- fires a trigger overrides the trigger's own conflict clause, and the app writes with upserts.
CREATE TRIGGER cloud_sync_account_ins AFTER INSERT ON account WHEN NOT EXISTS (SELECT 1 FROM cloud_sync_pulling) BEGIN UPDATE cloud_sync_outbox SET stamp = (SELECT MAX(stamp) + 1 FROM cloud_sync_outbox) WHERE tbl = 'account' AND row_id = NEW.rowid; INSERT INTO cloud_sync_outbox (tbl, row_id, stamp) SELECT 'account', NEW.rowid, (SELECT COALESCE(MAX(stamp), 0) + 1 FROM cloud_sync_outbox) WHERE NOT EXISTS (SELECT 1 FROM cloud_sync_outbox WHERE tbl = 'account' AND row_id = NEW.rowid); END;
CREATE TRIGGER cloud_sync_account_upd AFTER UPDATE ON account WHEN NOT EXISTS (SELECT 1 FROM cloud_sync_pulling) BEGIN UPDATE cloud_sync_outbox SET stamp = (SELECT MAX(stamp) + 1 FROM cloud_sync_outbox) WHERE tbl = 'account' AND row_id = NEW.rowid; INSERT INTO cloud_sync_outbox (tbl, row_id, stamp) SELECT 'account', NEW.rowid, (SELECT COALESCE(MAX(stamp), 0) + 1 FROM cloud_sync_outbox) WHERE NOT EXISTS (SELECT 1 FROM cloud_sync_outbox WHERE tbl = 'account' AND row_id = NEW.rowid); END;
