CREATE TRIGGER cloud_sync_shopping_trips_ins AFTER INSERT ON shopping_trips WHEN NOT EXISTS (SELECT 1 FROM cloud_sync_pulling) BEGIN UPDATE cloud_sync_outbox SET stamp = (SELECT MAX(stamp) + 1 FROM cloud_sync_outbox) WHERE tbl = 'shopping_trips' AND row_id = NEW.rowid; INSERT INTO cloud_sync_outbox (tbl, row_id, stamp) SELECT 'shopping_trips', NEW.rowid, (SELECT COALESCE(MAX(stamp), 0) + 1 FROM cloud_sync_outbox) WHERE NOT EXISTS (SELECT 1 FROM cloud_sync_outbox WHERE tbl = 'shopping_trips' AND row_id = NEW.rowid); END;
CREATE TRIGGER cloud_sync_shopping_trips_upd AFTER UPDATE ON shopping_trips WHEN NOT EXISTS (SELECT 1 FROM cloud_sync_pulling) BEGIN UPDATE cloud_sync_outbox SET stamp = (SELECT MAX(stamp) + 1 FROM cloud_sync_outbox) WHERE tbl = 'shopping_trips' AND row_id = NEW.rowid; INSERT INTO cloud_sync_outbox (tbl, row_id, stamp) SELECT 'shopping_trips', NEW.rowid, (SELECT COALESCE(MAX(stamp), 0) + 1 FROM cloud_sync_outbox) WHERE NOT EXISTS (SELECT 1 FROM cloud_sync_outbox WHERE tbl = 'shopping_trips' AND row_id = NEW.rowid); END;

